INSERT INTO dataset_sheet (
    dataset_id, sheet_index, sheet_name, row_count, column_count,
    preview_storage_ref, created_at, updated_at
) VALUES (
    #{datasetId}, #{sheetIndex}, #{sheetName}, #{rowCount}, #{columnCount},
    #{previewStorageRef}, #{createdAt}, #{updatedAt}
)

INSERT INTO dataset_column (
    dataset_id, sheet_id, ordinal_position, column_name, normalized_name,
    inferred_type, effective_type, nullable, sample_values_json,
    version, created_at, updated_at
) VALUES (
    #{datasetId}, #{sheetId}, #{ordinalPosition}, #{columnName}, #{normalizedName},
    #{inferredType}, #{effectiveType}, #{nullable}, #{sampleValuesJson},
    #{version}, #{createdAt}, #{updatedAt}
)

INSERT INTO dataset_profile (
    dataset_id, sheet_id, profile_version, row_count, column_count,
    summary_json, quality_json, profile_storage_ref, created_at
) VALUES (
    #{datasetId}, #{sheetId}, #{profileVersion}, #{rowCount}, #{columnCount},
    #{summaryJson}, #{qualityJson}, #{profileStorageRef}, #{createdAt}
)

